// This file is generated by AI.

// 自绘窗口标题栏 (取代系统原生标题栏)。
//
// 主窗口在 tauri.conf.json 里关掉了原生边框 (`decorations: false`), 由这条栏接管拖拽
// 与窗口按钮, 并顺带承载"主题 / 设置"两个入口 —— 开始界面与编辑界面共用同一条栏,
// 因此这两个入口在任何页面都出现在同一个位置 (过去它们在两个页面各写了一遍)。
//
// 拖拽与双击最大化交给 Tauri 的 drag region (`data-tauri-drag-region`), 不自己转发
// 鼠标事件: 自己实现容易在按钮上误触发拖拽, 也拿不到系统级的窗口吸附行为。

import { getCurrentWindow } from '@tauri-apps/api/window';
import {
  DismissRegular,
  MaximizeRegular,
  SettingsRegular,
  SquareMultipleRegular,
  SubtractRegular,
  WeatherMoonRegular,
  WeatherSunnyRegular,
} from '@fluentui/react-icons';
import { useEffect, useState } from 'react';

import { useAppStore } from '../state/store';

export function TitleBar() {
  const theme = useAppStore((s) => s.theme);
  const updateSettings = useAppStore((s) => s.updateSettings);
  const setSettingsOpen = useAppStore((s) => s.setSettingsOpen);
  const setSettingsCategory = useAppStore((s) => s.setSettingsCategory);
  /** 是否已最大化: 决定中间那个按钮是"最大化"还是"还原" */
  const [maximized, setMaximized] = useState(false);

  /*
   * 最大化状态只能由窗口事件推出来。
   *
   * 用 `onResized` 而不是只在挂载时问一次: 用户可以用系统快捷键或拖到屏幕边缘最大化,
   * 那时按钮图标不改就成了骗人的。窗口尺寸不变时 `isMaximized` 的结果也不会变, 因此
   * 这里不需要额外去重。
   */
  useEffect(() => {
    const win = getCurrentWindow();
    let disposed = false;
    const sync = () => {
      void win.isMaximized().then((value) => {
        if (!disposed) setMaximized(value);
      });
    };
    sync();
    const unlisten = win.onResized(sync);
    return () => {
      disposed = true;
      void unlisten.then((off) => off());
    };
  }, []);

  const win = getCurrentWindow();
  const dark = theme === 'dark';

  return (
    <header className="title-bar" data-tauri-drag-region>
      <div className="title-bar-brand" data-tauri-drag-region>
        {/* 应用自己的图标 (与任务栏/安装包同一个), 不用图标字体凑一个 */}
        <img className="title-bar-mark" src="/ink-icon.svg" alt="" draggable={false} />
        <span className="title-bar-name">WebGAL Ink</span>
      </div>

      <div className="title-bar-spacer" data-tauri-drag-region />

      <div className="title-bar-actions">
        <button
          type="button"
          className="title-bar-action"
          title={dark ? '切换到浅色主题' : '切换到深色主题'}
          onClick={() => updateSettings({ theme: dark ? 'light' : 'dark' })}
        >
          {dark ? <WeatherSunnyRegular /> : <WeatherMoonRegular />}
        </button>
        <button
          type="button"
          className="title-bar-action"
          title="设置"
          onClick={() => {
            setSettingsCategory('editor');
            setSettingsOpen(true);
          }}
        >
          <SettingsRegular />
        </button>
      </div>

      <div className="window-controls">
        <button
          type="button"
          className="window-control"
          title="最小化"
          aria-label="最小化"
          onClick={() => void win.minimize()}
        >
          <SubtractRegular />
        </button>
        <button
          type="button"
          className="window-control"
          title={maximized ? '向下还原' : '最大化'}
          aria-label={maximized ? '向下还原' : '最大化'}
          onClick={() => void win.toggleMaximize()}
        >
          {maximized ? <SquareMultipleRegular /> : <MaximizeRegular />}
        </button>
        <button
          type="button"
          className="window-control window-control-close"
          title="关闭"
          aria-label="关闭"
          onClick={() => void win.close()}
        >
          <DismissRegular />
        </button>
      </div>
    </header>
  );
}
